local integers = require "wa.integers"
local items = require "wa.items"
local variables = require "wa.variables"

local R = require "core.lib.rathena"
local WARP_FREE_TICKET = items.id "Warp_Free_Ticket"
local TEMP_WRPC_TEXT = variables.character_temporary_table "wrpc_text"
local TEMP_WRPP = variables.character_temporary_table "wrpp"
local TEMP_WRPD_TEXT = variables.character_temporary_table "wrpd_text"
local RESRVPTS = variables.character_integer "resrvpts"

return function(player, conversation, npc, ...)
  local j = 0
  local args = table.pack(...)
  conversation:say("[Kafra Employee]", "Please choose", "your destination.")
  conversation:wait_for_next()
  j = (conversation:choose(R.menu(R.aimplode(TEMP_WRPC_TEXT, player, ":"))) - 1)
  if (R.aget(TEMP_WRPC_TEXT, player, j, "") == "Cancel") then
    do return end
  end
  if ((player:count_item(WARP_FREE_TICKET) > 0) and (R.arg(args, 0) ~= 2)) then
    player:take_item(WARP_FREE_TICKET, 1)
  else
    if (player.zeny < R.aget(TEMP_WRPP, player, j, 0)) then
      conversation:say("[Kafra Employee]", "I'm sorry, but you don't have", "enough zeny for the Teleport", "Service. The fee to teleport", "to " .. R.aget(TEMP_WRPD_TEXT, player, j, "") .. " is " .. R.aget(TEMP_WRPP, player, j, 0) .. " zeny.")
      conversation:hide_image()
      R.stop()
    end
    player:pay_zeny(R.aget(TEMP_WRPP, player, j, 0))
    RESRVPTS:add(player, integers.divide_truncated(R.aget(TEMP_WRPP, player, j, 0), 16))
  end
  conversation:hide_image()
  if (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Al De Baran") then
    player:warp("aldebaran", 168, 112)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Alberta") then
    player:warp("alberta", 117, 56)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Comodo") then
    player:warp("comodo", 209, 143)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Comodo Pharos Beacon") then
    player:warp("cmd_fild07", 127, 134)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Geffen") then
    player:warp("geffen", 120, 39)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Izlude") then
    do
      player:warp("izlude", 128, 98)
    end
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Juno") then
    player:warp("yuno", 158, 125)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Mjolnir Dead Pit") then
    player:warp("mjolnir_02", 99, 351)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Morocc") then
    player:warp("morocc", 156, 46)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Orc Dungeon") then
    player:warp("gef_fild10", 52, 326)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Payon") then
    player:warp("payon", 161, 58)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Prontera") then
    player:warp("prontera", 116, 72)
  elseif (R.aget(TEMP_WRPD_TEXT, player, j, "") == "Umbala") then
    player:warp("umbala", 100, 154)
  end
  R.stop()
end
